(function () {
  function rankMap(data) {
    var map = {};
    if (data && Array.isArray(data.contributors)) {
      data.contributors.forEach(function (c) {
        if (c && c.login) map[String(c.login).toLowerCase()] = c;
      });
    }
    return map;
  }

  async function loadRanks() {
    try {
      // Generated by scripts/ranks.mjs so the client and the static pages
      // agree on the same rank data.
      const res = await fetch("/assets/data/contributor-ranks.json", { cache: "no-cache" });
      if (!res.ok) return {};
      return rankMap(await res.json());
    } catch (_) {
      return {};
    }
  }

  async function loadContributors() {
    const repo = (window.__WAFPP_CONTRIB__ || {}).repo || "waf2p/waf2p.github.io";
    const status = document.getElementById("github-contrib-status");
    const wrap = document.getElementById("github-contributors");
    if (!status || !wrap) return;

    try {
      // Prefer build-time cache (generated by Jekyll plugin) to avoid rate limits.
      // Falls back to live GitHub API if the cache is missing.
      let data = null;
      try {
        const cached = await fetch(`/assets/data/github-contributors.json`, { cache: "no-cache" });
        if (cached.ok) {
          const cachedJson = await cached.json();
          data = cachedJson.contributors || cachedJson;
        }
      } catch (_) {}

      if (!data) {
        const res = await fetch(`https://api.github.com/repos/${repo}/contributors?per_page=12`);
        if (!res.ok) throw new Error("GitHub API error");
        data = await res.json();
      }

      const ranks = await loadRanks();

      wrap.innerHTML = "";
      data.slice(0, 12).forEach(c => {
        const rank = ranks[String(c.login).toLowerCase()];
        const a = document.createElement("a");
        a.className = "wf6-community__contributor";
        a.href = c.html_url;
        a.target = "_blank";
        a.rel = "noopener";
        if (rank) {
          a.classList.add("has-rank");
          a.style.setProperty("--rank-color", rank.rank_color || "var(--border)");
          a.title = rank.rank_label + " — " + rank.points + " pts" + (
            rank.points_to_next
              ? " · " + rank.points_to_next + " pts to " + rank.next_rank_label
              : " · top rank"
          );
          a.setAttribute("aria-label", a.title);
        } else {
          a.title = c.login;
        }
        const img = document.createElement("img");
        img.src = c.avatar_url;
        img.alt = c.login;
        a.appendChild(img);
        wrap.appendChild(a);
      });

      status.textContent = "";
    } catch (e) {
      status.textContent = "—";
      console.debug(e);
    }
  }
  window.addEventListener("DOMContentLoaded", loadContributors);
})();